from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, x in enumerate(nums, 1):
            prefix[i] = prefix[i - 1] + x

        neg_inf = -10**18
        prev = [0] * (n + 1)

        for _ in range(k):
            curr = [neg_inf] * (n + 1)
            best_start = neg_inf

            for i in range(1, n + 1):
                curr[i] = curr[i - 1]

                if i >= m:
                    start = i - m
                    best_start = max(best_start, prev[start] - prefix[start])
                    curr[i] = max(curr[i], prefix[i] + best_start)

            prev = curr

        return prev[n]
